  console.log(`${C.bold}${C.cyan}   CINEJOY-WEBOS: DETAILS <-> PLAYER DEEP JOURNEY STRESS SUITE          ${C.reset}`);
  console.log(`${C.bold}${C.cyan}========================================================================\n${C.reset}`);

