    const { app } = createDom();
    app.init();
    assert(app.state.currentView === 'home', 'Should start on home');

    app.openDetails({ title: 'Dune: Part Two' });
    assert(app.state.currentView === 'details', 'Should be in details');

    app.switchView('player');
    assert(app.state.currentView === 'player', 'Should be in player');

    app.exitPlayer();
    assert(app.state.currentView === 'details', 'exitPlayer should return to details');

    app.handleBackNavigation();
    assert(app.state.currentView !== 'player', 'MUST NOT re-enter player');
    assert(app.state.currentView === 'home', `Expected return to 'home', got '${app.state.currentView}'`);

    // Another back on home should stay on home
    app.handleBackNavigation();
    assert(app.state.currentView === 'home', 'Back on home should stay on home');
  });

  // Test 2: Requirement 2.2: movies -> details -> player -> exitPlayer -> details -> Back
  await test('movies -> details -> player -> exitPlayer -> details -> Back (must return to movies)', async () => {
    const { app } = createDom('http://localhost/#movies');
    app.init();
    assert(app.state.currentView === 'movies', 'Should start on movies');

    app.openDetails({ title: 'Oppenheimer', year: '2023', rating: '8.9' });
    assert(app.state.currentView === 'details', 'Should be in details');
    assert(app.state.detailsOriginView === 'movies', 'Origin view should be movies');

    app.switchView('player');
    assert(app.state.currentView === 'player', 'Should be in player');

    app.exitPlayer();
    assert(app.state.currentView === 'details', 'exitPlayer should return to details');

    // Press Back on details
    app.handleBackNavigation();
    assert(app.state.currentView !== 'player', 'MUST NOT re-enter player');
    assert(app.state.currentView === 'movies', `Expected return to 'movies', got '${app.state.currentView}'`);

    // Press Back on movies -> should return to home
    app.handleBackNavigation();
    assert(app.state.currentView === 'home', `Expected Back from movies to return to 'home', got '${app.state.currentView}'`);

    // Press Back on home -> stays on home (webOS app exit threshold)
    app.handleBackNavigation();
    assert(app.state.currentView === 'home', 'Expected Back on home to remain on home');
  });

  // Test 3: Requirement 2.3: series -> details -> related details -> player -> exitPlayer -> Back -> Back
  await test('series -> details -> related details -> player -> exitPlayer -> Back -> Back (must safely escape to series/home)', async () => {
    const { app } = createDom('http://localhost/#series');
    app.init();
    assert(app.state.currentView === 'series', 'Should start on series');

    // Details 1
    app.openDetails({ title: 'Breaking Bad', year: '2008', rating: '9.5' });
    assert(app.state.currentView === 'details', 'Should be in details 1');
    assert(app.state.detailsOriginView === 'series', 'Origin should be series');

    // Related Details 2
    app.openDetails({ title: 'Better Call Saul', year: '2015', rating: '9.0' });
    assert(app.state.currentView === 'details', 'Should still be in details 2');
    assert(app.state.detailsOriginView === 'series', 'Origin must remain series across related items');

    // Play
    app.switchView('player');
    assert(app.state.currentView === 'player', 'Should be in player');

    // Exit player back to details
    app.exitPlayer();
    assert(app.state.currentView === 'details', 'Should return to details');

    // 1st Back: Must escape details to series
    app.handleBackNavigation();
    assert(app.state.currentView !== 'player', 'MUST NOT re-enter player');
    assert(app.state.currentView !== 'details', 'MUST NOT get trapped in details');
    assert(app.state.currentView === 'series', `1st Back must return to 'series', got '${app.state.currentView}'`);

    // 2nd Back: Must escape series to home
    app.handleBackNavigation();
    assert(app.state.currentView === 'home', `2nd Back must return to 'home', got '${app.state.currentView}'`);

    // 3rd Back: Exit threshold on home
    app.handleBackNavigation();
    assert(app.state.currentView === 'home', '3rd Back must stay on home');
